use super::*;
struct Source<'a>{held:&'a serde_json::Value,delta:&'a serde_json::Value}
impl KeyedSource for Source<'_>{
 fn held_len(&self)->usize{self.held.as_array().unwrap().len()}fn held_key(&self,i:usize)->&str{self.held[i].as_str().unwrap()}
 fn removed_len(&self)->usize{self.delta["removed"].as_array().unwrap().len()}fn removed(&self,i:usize)->(&str,usize){(self.delta["removed"][i]["id"].as_str().unwrap(),self.delta["removed"][i]["index"].as_u64().unwrap() as usize)}
 fn inserted_len(&self)->usize{self.delta["inserted"].as_array().unwrap().len()}fn inserted(&self,i:usize)->(&str,usize){(self.delta["inserted"][i]["id"].as_str().unwrap(),self.delta["inserted"][i]["index"].as_u64().unwrap() as usize)}
 fn moved_len(&self)->usize{self.delta["moved"].as_array().unwrap().len()}fn moved(&self,i:usize)->(&str,usize,usize){let row=&self.delta["moved"][i];(row["id"].as_str().unwrap(),row["from"].as_u64().unwrap() as usize,row["to"].as_u64().unwrap() as usize)}
 fn modified_len(&self)->usize{self.delta["modified"].as_array().unwrap().len()}fn modified_key(&self,i:usize)->&str{self.delta["modified"][i]["id"].as_str().unwrap()}
}
fn grant(d:RetirementDemand)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.release_bytes,maximum_depth:d.depth}}
fn close(plan:&mut KeyedPlan){plan.begin_close();for _ in 0..100000{if plan.terminal_is_empty(){return}let d=plan.close_demand();assert_eq!(plan.close_step(Default::default()).unwrap(),Default::default());plan.close_step(grant(d)).unwrap();}panic!("keyed metadata close stalled")}
#[test]
fn neutral_keyed_preflight_refusal_and_cancel_laws(){let corpus:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🔣️.json")).unwrap();for row in corpus["cases"].as_array().unwrap(){let source=Source{held:&row["held"],delta:&row["delta"]};let mut plan=KeyedPlan::new();let mut turns=0;loop{let d=plan.demand(&source).unwrap();for axis in 0..4{let mut short=grant(d);match axis{0=>short.maximum_items=0,1=>short.maximum_copy_bytes=d.copy_bytes-1,2=>{if d.capacity_bytes==0{continue}short.maximum_capacity_bytes=d.capacity_bytes-1},_=>short.maximum_depth=0}assert_eq!(plan.advance(&source,short).unwrap().progress,Default::default());}let step=plan.advance(&source,grant(d)).unwrap();turns+=1;assert!(turns<100000);if let Some(error)=step.error{assert_eq!(error,row["error"].as_str().unwrap());break}if step.done{assert!(row.get("error").is_none());let expected=row["origins"].as_array().unwrap();for(at,witness)in plan.origins().unwrap().iter().zip(expected){let at=at.unwrap();assert_eq!(at.inserted,witness[0]=="inserted");assert_eq!(at.index,witness[1].as_u64().unwrap() as usize);}assert_eq!(plan.modification_targets().unwrap(),row["modTargets"].as_array().unwrap().iter().map(|v|v.as_u64().unwrap() as usize).collect::<Vec<_>>());break}}
 close(&mut plan);for cut in[0,1,7,turns.saturating_sub(1)]{let mut cancelled=KeyedPlan::new();for _ in 0..cut{let d=cancelled.demand(&source).unwrap();let step=cancelled.advance(&source,grant(d)).unwrap();if step.done||step.error.is_some(){break}}close(&mut cancelled);}}
}
